const coverAutomation = global.get("coverAutomation");
if (!coverAutomation || typeof coverAutomation.renderDetailPage !== "function") {
    msg.statusCode = 500;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload = "cover automation helper missing";
    return msg;
}

const runtime = global.get("smarthome_runtime");
const params = msg.req && msg.req.params ? msg.req.params : {};
const query = msg.req && msg.req.query ? msg.req.query : {};
const deviceId = params.device_id || "";
const notice = query.saved === "1" ? "Zeitautomatik gespeichert." : "";
const result = coverAutomation.renderDetailPage(runtime, deviceId, notice);
msg.statusCode = result.statusCode || 200;
msg.headers = { "Content-Type": "text/html; charset=utf-8" };
msg.payload = result.html;
return msg;

const coverAutomation = global.get("coverAutomation");
const timeHelpers = global.get("timeHelpers");
const runtime = global.get("smarthome_runtime");
if (!coverAutomation || typeof coverAutomation.saveDeviceConfig !== "function") {
    msg.statusCode = 500;
    msg.payload = { ok: false, error: "cover_automation_unavailable", message: "cover automation helper missing" };
    return msg;
}

const params = msg.req && msg.req.params ? msg.req.params : {};
const deviceId = params.device_id || "";
const device = runtime && runtime.devices ? runtime.devices[deviceId] : null;
if (!device) {
    msg.statusCode = 404;
    msg.payload = { ok: false, error: "device_not_found", message: "device not found" };
    return msg;
}

const result = coverAutomation.saveDeviceConfig(deviceId, msg.payload, timeHelpers.nowIso());
msg.statusCode = result.ok ? 200 : 400;
msg.payload = result.ok
    ? { ok: true, device_id: deviceId, config: result.config }
    : { ok: false, error: result.error, message: result.message };
return msg;

const coverAutomation = global.get("coverAutomation");
const commandMinimal = global.get("commandMinimal");
const timeHelpers = global.get("timeHelpers");
const runtime = global.get("smarthome_runtime");
if (!coverAutomation || typeof coverAutomation.buildDueMessages !== "function") {
    return null;
}

const now = timeHelpers.nowIso();
const result = coverAutomation.buildDueMessages(runtime, commandMinimal, now);
if (Array.isArray(result.errors) && result.errors.length > 0) {
    node.warn(result.errors.map((entry) => `${entry.device_id} ${entry.slot}: ${entry.error}`).join(" | "));
}
if (!Array.isArray(result.messages) || result.messages.length === 0) {
    return null;
}
return [result.messages, null];
